import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import { fileURLToPath } from "node:url";

export default defineConfig({
  plugins: [react(), tailwindcss()],
  // Live mode in development: /api goes to a local `notary serve` (read-only, loopback).
  // When it is not running the probe fails and the app falls back to the static files.
  server: {
    proxy: {
      "/api": {
        target: process.env.NOTARY_API_PROXY ?? "http://127.0.0.1:8787",
        configure: (proxy) => {
          proxy.on("error", (_err, _req, res) => {
            if ("writeHead" in res && !res.headersSent) {
              res.writeHead(503, { "content-type": "text/plain" });
              res.end("notary serve is not running");
            }
          });
        },
      },
    },
  },
  resolve: {
    alias: { "@": fileURLToPath(new URL("./src", import.meta.url)) },
    dedupe: ["react", "react-dom", "zod"],
  },
  build: {
    rollupOptions: {
      output: {
        // Two named chunks only. A hand-made "charts" chunk (recharts, d3-*) once became circular
        // with "ui" (TDZ crash at startup, DECISIONS #128), so nothing else is grouped by hand.
        // zod and the React core import nothing outside themselves, so neither can form a cycle.
        manualChunks(id) {
          if (id.includes("node_modules")) {
            if (/[\\/]zod[\\/]/.test(id)) return "schema";
            // Only what every route needs shares "vendor". Dashboard-only libraries (recharts,
            // d3, cmdk, ...) are left to Rollup's splitting so they load with the lazy /app
            // chunk, never on the landing (R4 Lighthouse).
            if (/[\\/]node_modules[\\/](react|react-dom|scheduler|react-router)[\\/]/.test(id)) return "vendor";
          }
        },
      },
    },
  },
});

// THE route table for /app. Sidebar, top bar title, document titles, the command palette and the
// router all read it. Six pages are in the sidebar (Run, Certificates, Approvals, Business, Incidents, Chat); Report is
// linked from the sidebar footer; a certificate has its own page.
import type { ReactElement } from "react";
import { matchPath } from "react-router";
import { RunPage } from "./pages/run/RunPage";
import { CertificatesPage } from "./pages/certificates/CertificatesPage";
import { CertificateDetailPage } from "./pages/certificates/CertificateDetailPage";
import { ApprovalsPage } from "./pages/approvals";
import { ChatPage } from "./pages/chat/ChatPage";
import { BusinessPage } from "./pages/business/BusinessPage";
import { IncidentsPage } from "./pages/incidents/IncidentsPage";
import { ReportPage } from "./pages/report/ReportPage";

export type AppRoute = {
  id: string;
  /** Absolute path under /app; `:param` segments name the record. */
  path: string;
  title: string;
  description: string;
  /** In the sidebar (exactly six routes). */
  nav?: boolean;
  /** Sidebar count: approvals waiting for a human. */
  badge?: "approvals";
  /** Route id of the list page a record belongs to (top bar trail; switching runs returns there). */
  parent?: string;
  /** Record kind this route renders, for routes with a `:param`. */
  record?: "certificate";
  /** Renders without a selected, verified run (it handles empty and loading states itself). */
  ungated?: boolean;
  element: ReactElement;
};

export const routes: AppRoute[] = [
  { id: "run", path: "/app/run", title: "Run", description: "One run, step by step: what the agent did and why.", nav: true, ungated: true, element: <RunPage /> },
  { id: "certificates", path: "/app/certificates", title: "Certificates", description: "API behavior certified within a scope, and revocable.", nav: true, element: <CertificatesPage /> },
  { id: "certificate", path: "/app/certificates/:certificateId", title: "Certificate", description: "One certificate and the evidence behind it.", parent: "certificates", record: "certificate", element: <CertificateDetailPage /> },
  { id: "approvals", path: "/app/approvals", title: "Approvals", description: "Held money actions waiting for a human.", nav: true, badge: "approvals", element: <ApprovalsPage /> },
  { id: "business", path: "/app/business", title: "Business", description: "Unit economics from real runs and the business plan modeled in cfo.ai.", nav: true, ungated: true, element: <BusinessPage /> },
  { id: "incidents", path: "/app/incidents", title: "Incidents", description: "What went wrong while the agents worked, and how it was resolved.", nav: true, ungated: true, element: <IncidentsPage /> },
  { id: "chat", path: "/app/chat", title: "Chat", description: "Ask Notary about runs, certificates and the APIs it checks; answers cite records.", nav: true, ungated: true, element: <ChatPage /> },
  { id: "report", path: "/app/report", title: "Report", description: "Run comparison, cost per run, connections and receipts.", ungated: true, element: <ReportPage /> },
];

/** The sidebar, in order. */
export const navRoutes = () => routes.filter((r) => r.nav);

export type Redirect = {
  from: string;
  /** Target path (may carry a query); `:param` values of `from` are substituted. */
  to: string;
};

/**
 * Old URLs, kept working for shared links. The old query string is kept and merged with the
 * target's (the target's own params win, e.g. ?run= of /app/runs/:runId).
 */
export const redirects: Redirect[] = [
  { from: "/app", to: "/app/run" },
  { from: "/app/overview", to: "/app/run" },
  { from: "/app/mission-control", to: "/app/run" },
  { from: "/app/runs", to: "/app/run" },
  { from: "/app/runs/:runId", to: "/app/run?run=:runId" },
  { from: "/app/queue", to: "/app/run" },
  { from: "/app/queue/:decisionId", to: "/app/run?decision=:decisionId" },
  { from: "/app/probes", to: "/app/run" },
  { from: "/app/probes/:probeId", to: "/app/run?probe=:probeId" },
  { from: "/app/beliefs", to: "/app/certificates" },
  { from: "/app/beliefs/:beliefId", to: "/app/certificates?belief=:beliefId" },
  { from: "/app/reports", to: "/app/certificates" },
  { from: "/app/reports/:tool", to: "/app/certificates?tool=:tool" },
  { from: "/app/api-report", to: "/app/certificates" },
  { from: "/app/revocation-demo", to: "/app/certificates" },
  { from: "/app/revocation", to: "/app/certificates" },
  { from: "/app/economics", to: "/app/business" },
  { from: "/app/evidence", to: "/app/report" },
  { from: "/app/comparison", to: "/app/report" },
  { from: "/app/ask", to: "/app/chat" },
];

/** The target of a redirect for concrete params, old query merged (target params win). */
export function redirectTarget(r: Redirect, params: Record<string, string | undefined>, search = ""): string {
  const filled = r.to.replace(/:([A-Za-z]+)/g, (_, name: string) => encodeURIComponent(params[name] ?? ""));
  const [path, query = ""] = filled.split("?", 2) as [string, string?];
  const merged = new URLSearchParams(search);
  for (const [k, v] of new URLSearchParams(query)) merged.set(k, v);
  const q = merged.toString();
  return q ? `${path}?${q}` : path;
}

export const routeById = (id: string) => routes.find((r) => r.id === id);

/** The route (and its params) for a pathname. Most specific match wins. */
export function matchAppRoute(
  pathname: string,
): { route: AppRoute; params: Record<string, string | undefined> } | undefined {
  const normalized = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;
  for (const route of [...routes].sort((a, b) => b.path.split("/").length - a.path.split("/").length)) {
    const m = matchPath({ path: route.path, end: true }, normalized);
    if (m) return { route, params: m.params };
  }
  return undefined;
}

/** Path relative to the /app/* splat, for <Route path>. */
export const relativePath = (path: string) => (path === "/app" ? "" : path.replace(/^\/app\//, ""));
// Build/runtime environment for mode selection (see select.ts). No I/O.

export const DEFAULT_API_BASE = "http://localhost:8787";
export type SelectEnv = {
  PROD?: boolean;
  VITE_NOTARY_API?: string;
  VITE_NOTARY_LIVE?: string;
};

const buildEnv = (): SelectEnv => import.meta.env as unknown as SelectEnv;

/** Base URL of the local API: VITE_NOTARY_API, else the serve default. "" = same origin. */
export function resolveApiBase(env: SelectEnv = buildEnv()): string {
  const set = env.VITE_NOTARY_API;
  if (set === undefined) return DEFAULT_API_BASE;
  return String(set).trim().replace(/\/+$/, "");
}

/** The hosted/production build: replay only, never probes. */
export function isHostedBuild(env: SelectEnv = buildEnv()): boolean {
  return env.PROD === true && env.VITE_NOTARY_LIVE !== "1";
}

const LOOPBACK_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]", "::1"]);

/**
 * Whether this page may probe the local API at all. Never on the hosted build. Otherwise only
 * from a loopback page (or a hostless context such as tests), unless VITE_NOTARY_API names the
 * API explicitly.
 */
export function shouldProbe(
  env: SelectEnv = buildEnv(),
  hostname: string | undefined = globalThis.location?.hostname,
): boolean {
  if (isHostedBuild(env)) return false;
  if (env.VITE_NOTARY_API !== undefined && env.VITE_NOTARY_API !== "") return true;
  if (!hostname) return true;
  return LOOPBACK_HOSTS.has(hostname) || hostname.endsWith(".localhost");
}
// Mode selection. LiveSource iff the API at VITE_NOTARY_API (default http://localhost:8787, the
// `notary serve` default port) answers GET /api/health with a schema-valid HealthResponse;
// otherwise ReplaySource. No global mode banner (K4): pages say "Start the server…" where a live
// action fails, and fixture runs keep their fixture note.
//
// The hosted (production) build is ALWAYS replay and never probes anything: `notary serve`
// accepts loopback requests only (DECISIONS #115), so a hosted page could never reach it and a
// probe would only log console errors (#133). A production build meant for local use can opt in
// with VITE_NOTARY_LIVE=1 at build time. In dev, a page served from a non-loopback host only
// probes when VITE_NOTARY_API is set explicitly. VITE_NOTARY_API="" (or "/") means same origin,
// i.e. the Vite dev proxy forwarding /api to 127.0.0.1:8787.
import { HealthResponseSchema, type HealthResponse } from "../../../core/src/schema";
import { globalFetch, type FetchImpl } from "./http";
import { LiveSource, type EventSourceCtor } from "./live";
import { PublishedFiles } from "./published";
import { ReplaySource } from "./replay";
import type { DataMode, DataSource } from "./types";
import { isHostedBuild, resolveApiBase, shouldProbe, type SelectEnv } from "./env";

export { DEFAULT_API_BASE, isHostedBuild, resolveApiBase, shouldProbe, type SelectEnv } from "./env";

export const HEALTH_TIMEOUT_MS = 1500;

export type HealthProbe =
  | { ok: true; health: HealthResponse }
  /** Nothing answered (refused, timeout, non-JSON, non-2xx). Quietly replay. */
  | { ok: false; reason: "unreachable" }
  /** Something answered with JSON that is not a HealthResponse: replay, and say why. */
  | { ok: false; reason: "invalid"; error: string };

/** GET <base>/api/health, validated with HealthResponseSchema. Never throws. */
export async function probeHealth(
  base: string,
  opts: { fetchImpl?: FetchImpl; timeoutMs?: number; signal?: AbortSignal } = {},
): Promise<HealthProbe> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? HEALTH_TIMEOUT_MS);
  const forward = () => controller.abort();
  opts.signal?.addEventListener("abort", forward, { once: true });
  let raw: unknown;
  try {
    const response = await (opts.fetchImpl ?? globalFetch)(`${base}/api/health`, {
      signal: controller.signal,
      cache: "no-store",
      headers: { accept: "application/json" },
    });
    if (!response.ok || !response.headers.get("content-type")?.includes("json"))
      return { ok: false, reason: "unreachable" };
    raw = await response.json();
  } catch {
    return { ok: false, reason: "unreachable" };
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", forward);
  }
  const parsed = HealthResponseSchema.safeParse(raw);
  return parsed.success
    ? { ok: true, health: parsed.data }
    : {
        ok: false,
        reason: "invalid",
        error: `The API at ${base || "this origin"} answered /api/health with something that is not a Notary health response, so this page is replaying published files.`,
      };
}

export type Selection = {
  source: DataSource;
  mode: DataMode;
  /** Live: the probe's health response. Replay: null. */
  health: HealthResponse | null;
  /** True on the hosted build (always replay, never probed). */
  hosted: boolean;
  apiBase: string;
  /** Why live mode was refused although something answered; null otherwise. */
  error: string | null;
};

export type SelectOptions = {
  env?: SelectEnv;
  hostname?: string;
  fetchImpl?: FetchImpl;
  EventSourceImpl?: EventSourceCtor;
  published?: PublishedFiles;
  timeoutMs?: number;
  signal?: AbortSignal;
};

/** The replay selection, known synchronously (used before/without a probe). */
export function replaySelection(opts: SelectOptions = {}): Selection {
  const env = opts.env ?? (import.meta.env as unknown as SelectEnv);
  return {
    source: new ReplaySource({ published: opts.published ?? new PublishedFiles({ fetchImpl: opts.fetchImpl }) }),
    mode: "replay",
    health: null,
    hosted: isHostedBuild(env),
    apiBase: resolveApiBase(env),
    error: null,
  };
}

/** Probe (when allowed) and pick the data source. Never throws. */
export async function selectDataSource(opts: SelectOptions = {}): Promise<Selection> {
  const env = opts.env ?? (import.meta.env as unknown as SelectEnv);
  const replay = replaySelection(opts);
  if (!shouldProbe(env, "hostname" in opts ? opts.hostname : globalThis.location?.hostname)) return replay;

