import { createRequire } from "node:module";
import { mkdirSync, writeFileSync } from "node:fs";
const require = createRequire("C:/Users/Parth Chilwerwar/Desktop/notary/packages/web/package.json");
const { chromium } = require("@playwright/test");

const base = process.env.BASE ?? "http://127.0.0.1:5197";
const out = process.env.OUT ?? "C:/Users/PARTHC~1/AppData/Local/Temp/claude/C--Users-Parth-Chilwerwar-Desktop-notary/ff1243e8-a2bc-405f-820f-cf11571bb5d5/scratchpad/shots";
const tag = process.env.TAG ?? "prod";
mkdirSync(out, { recursive: true });
const routes = (process.env.ROUTES ?? "/,/docs,/app,/app/run,/app/certificates,/app/approvals,/app/business,/app/incidents,/app/chat,/app/report,/app/run?fixtures=1,/app/nope,/nope").split(",");

const browser = await chromium.launch({ channel: "chrome", headless: true });
const report = [];
for (const width of [1440, 390]) {
  const ctx = await browser.newContext({ viewport: { width, height: width === 1440 ? 900 : 844 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  let cur = null;
  page.on("pageerror", (e) => cur?.pageErrors.push(e.message));
  page.on("console", (m) => { if (m.type() === "error" || m.type() === "warning") cur?.console.push(`${m.type()}: ${m.text().slice(0, 300)}`); });
  page.on("requestfailed", (r) => cur?.failed.push(`${r.url()} ${r.failure()?.errorText}`));
  page.on("response", (r) => { if (r.status() >= 400) cur?.bad.push(`${r.status()} ${r.url()}`); });
  for (const route of routes) {
    cur = { width, route, pageErrors: [], console: [], failed: [], bad: [] };
    const t0 = Date.now();
    try {
      await page.goto(base + route, { waitUntil: "networkidle", timeout: 30000 });
    } catch (e) { cur.gotoError = e.message.slice(0, 200); }
    await page.waitForTimeout(1500);
    cur.loadMs = Date.now() - t0;
    cur.finalUrl = page.url().replace(base, "");
    const info = await page.evaluate(() => {
      const vis = (el) => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return r.width > 0 && r.height > 0 && s.visibility !== "hidden" && s.display !== "none"; };
      const overflowers = [];
      const W = document.documentElement.clientWidth;
      for (const el of document.querySelectorAll("body *")) {
        const r = el.getBoundingClientRect();
        if (r.right > W + 1 && r.width > 0 && vis(el)) {
          // skip if an ancestor clips overflow
          let p = el.parentElement, clipped = false;
          while (p && p !== document.body) { const s = getComputedStyle(p); if (/(hidden|auto|scroll|clip)/.test(s.overflowX)) { clipped = true; break; } p = p.parentElement; }
          if (!clipped) overflowers.push(`${el.tagName.toLowerCase()}.${String(el.className).slice(0, 60)} right=${Math.round(r.right)}`);
        }
      }
      return {
        title: document.title,
        h1: [...document.querySelectorAll("h1")].map((h) => h.textContent.trim().slice(0, 80)),
        scrollW: document.documentElement.scrollWidth, clientW: W,
        overflowers: overflowers.slice(0, 8),
        links: [...document.querySelectorAll("a[href]")].filter(vis).map((a) => ({ href: a.getAttribute("href"), text: (a.textContent || a.getAttribute("aria-label") || "").trim().slice(0, 50), target: a.target })),
        buttons: [...document.querySelectorAll("button,[role=button],[role=tab]")].filter(vis).map((b) => (b.textContent || b.getAttribute("aria-label") || "").trim().slice(0, 50)),
        skeletons: [...document.querySelectorAll("[aria-busy=true], .skeleton, .ui-skeleton")].filter(vis).length,
        notFound: /Page not found|No page lives/.test(document.body.innerText),
        fixtureBanner: /Fixture data/.test(document.body.innerText),
        bodyTextLen: document.body.innerText.length,
      };
    });
    Object.assign(cur, info);
    const slug = route.replace(/[^a-z0-9]+/gi, "_") || "root";
    await page.screenshot({ path: `${out}/${tag}-${width}-${slug}.png`, fullPage: false });
    report.push(cur);
  }
  await ctx.close();
}
await browser.close();
writeFileSync(`${out}/${tag}-crawl.json`, JSON.stringify(report, null, 2));
for (const r of report) {
  console.log(`\n[${r.width}] ${r.route} -> ${r.finalUrl} (${r.loadMs}ms) title="${r.title}" h1=${JSON.stringify(r.h1)} scrollW=${r.scrollW}/${r.clientW} skel=${r.skeletons} notFound=${r.notFound} fixture=${r.fixtureBanner} links=${r.links.length} buttons=${r.buttons.length}`);
  for (const k of ["gotoError", "pageErrors", "console", "failed", "bad", "overflowers"]) if (r[k] && (typeof r[k] === "string" || r[k].length)) console.log(`  ${k}: ${JSON.stringify(r[k])}`);
}

