          while (p && p !== document.body) { const s = getComputedStyle(p); if (/(hidden|auto|scroll|clip)/.test(s.overflowX)) { clipped = true; break; } p = p.parentElement; }
          if (!clipped) overflowers.push(`${el.tagName.toLowerCase()}.${String(el.className).slice(0, 60)} right=${Math.round(r.right)}`);
        }
      }
      return {
        title: document.title,
        h1: [...document.querySelectorAll("h1")].map((h) => h.textContent.trim().slice(0, 80)),
        scrollW: document.documentElement.scrollWidth, clientW: W,
        overflowers: overflowers.slice(0, 8),
        links: [...document.querySelectorAll("a[href]")].filter(vis).map((a) => ({ href: a.getAttribute("href"), text: (a.textContent || a.getAttribute("aria-label") || "").trim().slice(0, 50), target: a.target })),
        buttons: [...document.querySelectorAll("button,[role=button],[role=tab]")].filter(vis).map((b) => (b.textContent || b.getAttribute("aria-label") || "").trim().slice(0, 50)),
        skeletons: [...document.querySelectorAll("[aria-busy=true], .skeleton, .ui-skeleton")].filter(vis).length,
        notFound: /Page not found|No page lives/.test(document.body.innerText),
        fixtureBanner: /Fixture data/.test(document.body.innerText),
        bodyTextLen: document.body.innerText.length,
      };
    });
    Object.assign(cur, info);
    const slug = route.replace(/[^a-z0-9]+/gi, "_") || "root";
    await page.screenshot({ path: `${out}/${tag}-${width}-${slug}.png`, fullPage: false });
    report.push(cur);
  }
  await ctx.close();
}
await browser.close();
writeFileSync(`${out}/${tag}-crawl.json`, JSON.stringify(report, null, 2));
for (const r of report) {
  console.log(`\n[${r.width}] ${r.route} -> ${r.finalUrl} (${r.loadMs}ms) title="${r.title}" h1=${JSON.stringify(r.h1)} scrollW=${r.scrollW}/${r.clientW} skel=${r.skeletons} notFound=${r.notFound} fixture=${r.fixtureBanner} links=${r.links.length} buttons=${r.buttons.length}`);
  for (const k of ["gotoError", "pageErrors", "console", "failed", "bad", "overflowers"]) if (r[k] && (typeof r[k] === "string" || r[k].length)) console.log(`  ${k}: ${JSON.stringify(r[k])}`);
}

