import { createRequire } from "node:module";
const require = createRequire("C:/Users/Parth Chilwerwar/Desktop/notary/packages/web/package.json");
const { chromium } = require("@playwright/test");
const base = process.env.BASE ?? "http://127.0.0.1:5197";
const out = "C:/Users/PARTHC~1/AppData/Local/Temp/claude/C--Users-Parth-Chilwerwar-Desktop-notary/ff1243e8-a2bc-405f-820f-cf11571bb5d5/scratchpad/shots";
const width = Number(process.env.W ?? 1440);
const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({ viewport: { width, height: width === 1440 ? 900 : 844 }, acceptDownloads: true, permissions: ["clipboard-read", "clipboard-write"] });
const page = await ctx.newPage();
const errs = [];
page.on("pageerror", (e) => errs.push(`[${page.url().replace(base, "")}] pageerror ${e.message}`));
page.on("console", (m) => { if (m.type() === "error") errs.push(`[${page.url().replace(base, "")}] console ${m.text().slice(0, 200)}`); });
page.on("response", (r) => { if (r.status() >= 400) errs.push(`[${page.url().replace(base, "")}] ${r.status()} ${r.url()}`); });
const log = (...a) => console.log(...a);
const step = async (name, fn) => { try { await fn(); } catch (e) { log(`FAIL ${name}: ${e.message.split("\n")[0].slice(0, 300)}`); await page.screenshot({ path: `${out}/fail-${width}-${name.replace(/\W+/g, "_")}.png` }).catch(() => {}); } };
const go = async (p) => { await page.goto(base + p, { waitUntil: "networkidle" }); await page.waitForTimeout(800); };
const text = () => page.evaluate(() => document.body.innerText);

// ---- Run page
await step("run-picker", async () => {
  await go("/app/run");
  const sel = page.locator(".run-select select, .run-select [role=combobox], .run-select button").first();
  log("run picker tag:", await sel.evaluate((e) => e.tagName + " role=" + e.getAttribute("role")));
  const isSelect = await sel.evaluate((e) => e.tagName === "SELECT");
  if (isSelect) {
    const opts = await sel.locator("option").allTextContents();
    log("run options:", JSON.stringify(opts));
    for (const o of opts.slice(0, 8)) {
      await sel.selectOption({ label: o });
      await page.waitForTimeout(1200);
      const t = await page.evaluate(() => ({ url: location.search, h: document.querySelector("h1 + p, .page-sub, header p")?.textContent?.slice(0, 80), body: document.body.innerText.includes("Loading") }));
      log("  picked:", o.slice(0, 60), "->", JSON.stringify(t));
    }
  } else {
    await sel.click(); await page.waitForTimeout(500);
    const opts = await page.locator("[role=option]").allTextContents();
    log("run options:", JSON.stringify(opts));
    for (let i = 0; i < Math.min(opts.length, 8); i++) {
      if (i > 0) { await sel.click(); await page.waitForTimeout(400); }
      await page.locator("[role=option]").nth(i).click();
      await page.waitForTimeout(1500);
      const t = await page.evaluate(() => ({ url: location.search, sub: document.querySelector("main h1")?.parentElement?.innerText?.slice(0, 120).replace(/\n/g, " | ") }));
      log("  picked:", opts[i].slice(0, 60), "->", JSON.stringify(t));
    }
  }
});
await step("run-transcript", async () => {
  await go("/app/run?run=notarize-crustdata-20261012T011404Z");
  await page.getByRole("button", { name: "Instant" }).click(); await page.waitForTimeout(800);
  for (const n of ["Money actions", "Held", "Unsafe or revoked", "All"]) {
    const b = page.getByRole("button", { name: new RegExp("^" + n) }).first();
    await b.click(); await page.waitForTimeout(300);
    log(`filter ${n}: pressed=${await b.getAttribute("aria-pressed")} rows=${await page.locator(".transcript-row, [data-event-row], li[role=option], button.tr-row").count()}`);
  }
  await page.getByRole("button", { name: "In order" }).click(); await page.waitForTimeout(300);
  await page.getByRole("button", { name: "By stage" }).click(); await page.waitForTimeout(300);
  const before = await page.evaluate(() => document.body.innerText.match(/event (\d+) of (\d+)/)?.[0]);
  await page.locator("body").click({ position: { x: 5, y: 5 } }).catch(() => {});
  await page.keyboard.press("j"); await page.waitForTimeout(200); await page.keyboard.press("j"); await page.waitForTimeout(200);
  const afterJ = await page.evaluate(() => document.body.innerText.match(/event (\d+) of (\d+)/)?.[0]);
  await page.keyboard.press("k"); await page.waitForTimeout(200);
  const afterK = await page.evaluate(() => document.body.innerText.match(/event (\d+) of (\d+)/)?.[0]);
  log(`j/k: before=${before} after jj=${afterJ} after k=${afterK}`);
  await page.getByRole("button", { name: "Next event" }).click(); await page.waitForTimeout(200);
  log("after Next:", await page.evaluate(() => document.body.innerText.match(/event (\d+) of (\d+)/)?.[0]));
  await page.getByRole("button", { name: "Replay from start" }).click(); await page.waitForTimeout(1500);
  log("after replay from start (1.5s):", await page.evaluate(() => document.body.innerText.match(/(\d+) events?\s*·\s*\w+/)?.[0]));
  await page.getByRole("button", { name: "4×" }).click(); await page.waitForTimeout(3000);
  log("after 4x 3s:", await page.evaluate(() => document.body.innerText.match(/(\d+) events?\s*·\s*\w+/g)?.join(" / ")));
  await page.screenshot({ path: `${out}/int-${width}-run-crustdata.png`, fullPage: true });
});
// ---- Certificates
await step("certificates", async () => {
  await go("/app/certificates");
  for (const n of ["Active", "Revoked", "crustdata", "dodo", "All providers", "All"]) {
    await page.getByRole("link", { name: new RegExp("^" + n) }).first().click(); await page.waitForTimeout(500);
    log(`cert filter ${n}: url=${page.url().replace(base, "")} rows=${await page.locator("a[href*='/app/certificates/cert-']").count()}`);
  }
  const hrefs = await page.locator("a[href*='/app/certificates/cert-']").evaluateAll((as) => as.map((a) => a.getAttribute("href")));
  for (const h of hrefs) {
    await go(h);
    const t = await text();
    log(`cert detail ${h.split("?")[0]}: h1=${await page.locator("h1").first().textContent()} notFound=${/not found|No certificate/i.test(t)} hashErr=${/mismatch|tamper/i.test(t)} len=${t.length}`);
  }
  await page.screenshot({ path: `${out}/int-${width}-cert-detail.png`, fullPage: true });
  // links inside detail
  const dl = await page.locator("main a[href]").evaluateAll((as) => as.map((a) => a.getAttribute("href") + " [" + a.textContent.trim().slice(0, 40) + "]"));
  log("detail links:", JSON.stringify(dl));
  await go("/app/certificates");
  await page.getByRole("link", { name: "Ask about these" }).click(); await page.waitForTimeout(4000);
  log("ask about these ->", page.url().replace(base, ""), "| text has answer:", (await text()).slice(0, 0), (await page.locator("main").innerText()).slice(0, 400).replace(/\n/g, " | "));
  await page.screenshot({ path: `${out}/int-${width}-ask-about-these.png` });
});
// ---- Approvals (fixture)
await step("approvals-fixture", async () => {
  await go("/app/approvals?fixtures=1");
  const items = page.locator(".desk-item, [data-approval], main li");
  log("approvals fixture items:", await items.count());
  const btns = await page.locator("main button").evaluateAll((bs) => bs.map((b) => b.textContent.trim().slice(0, 40) + (b.disabled ? "(disabled)" : "")));
  log("approvals buttons:", JSON.stringify(btns.slice(0, 20)));
  const first = page.locator("main button").filter({ hasNotText: /^$/ }).first();
  if (await first.count()) { await first.click(); await page.waitForTimeout(600); }
  await page.screenshot({ path: `${out}/int-${width}-approvals-fixture.png`, fullPage: false });
  log("approvals fixture banner:", /Fixture data/.test(await text()));
});
// ---- Business CSV
await step("business-csv", async () => {
  await go("/app/business");
  const a = page.getByRole("link", { name: /Inputs for cfo.ai/ }).first();
  log("csv download attr:", await a.getAttribute("download"));
  const [dl] = await Promise.all([page.waitForEvent("download", { timeout: 8000 }), a.click()]);
  const p = await dl.path();
  const fs = await import("node:fs");
  const c = fs.readFileSync(p, "utf8");
  log("csv suggested name:", dl.suggestedFilename(), "lines:", c.trim().split("\n").length, "header:", c.split("\n")[0].slice(0, 120));
  await page.screenshot({ path: `${out}/int-${width}-business-full.png`, fullPage: true });
});
// ---- Incidents
await step("incidents", async () => {
  await go("/app/incidents");
  for (const n of ["Resolved", "Awaiting a human", "Open", "Warning", "Error", "Checker anomaly", "Adversary downgrade", "All", "Any severity", "Every kind"]) {
    await page.getByRole("link", { name: new RegExp("^" + n) }).first().click(); await page.waitForTimeout(400);
    const t = await page.locator("main").innerText();
    log(`inc filter ${n}: url=${page.url().replace(base, "").replace(/run=[^&]+&?/, "")} cards=${(t.match(/Adversary downgrade|Checker anomaly/g) || []).length} empty=${/No incident|Nothing/i.test(t)}`);
  }
  const copy = page.getByRole("button", { name: /Copy trace id/ }).first();
  if (await copy.count()) { await copy.click(); await page.waitForTimeout(400); log("clipboard after copy:", await page.evaluate(() => navigator.clipboard.readText()).catch((e) => "ERR " + e.message)); }
  else log("no copy button");
  const rec = page.getByRole("button", { name: /Records/ }).first();
  if (await rec.count()) { await rec.click(); await page.waitForTimeout(400); log("records expanded:", await rec.getAttribute("aria-expanded")); }
  // follow a certificate link from an incident
  const cl = page.locator("main a[href*='belief=']").first();
  if (await cl.count()) { const h = await cl.getAttribute("href"); await cl.click(); await page.waitForTimeout(1500); log("incident cert link", h, "->", page.url().replace(base, ""), "h1:", await page.locator("h1").first().textContent(), "| main:", (await page.locator("main").innerText()).slice(0, 200).replace(/\n/g, " | ")); await page.screenshot({ path: `${out}/int-${width}-incident-belief-link.png` }); }
});
// ---- Chat suggestions (replay)
await step("chat", async () => {
  await go("/app/chat");
  const sugg = page.locator(".chat-suggestions button, main button").filter({ hasText: /crustdata's enrich|Acme|adversary reject/ });
  const n = await sugg.count();
  for (let i = 0; i < n; i++) {
    await go("/app/chat");
    const s = page.locator(".chat-suggestions button, main button").filter({ hasText: /crustdata's enrich|Acme|adversary reject/ }).nth(i);
    const label = (await s.textContent()).slice(0, 50);
    await s.click();
    await page.waitForTimeout(7000);
    const t = await page.locator("main").innerText();
    log(`chat suggestion "${label}": len=${t.length} snippet=${t.slice(0, 700).replace(/\n/g, " | ")}`);
    await page.screenshot({ path: `${out}/int-${width}-chat-${i}.png`, fullPage: false });
  }
  // free text in replay
  await go("/app/chat");
  await page.getByPlaceholder(/Ask Notary/).fill("Which certificates are active?");
  await page.keyboard.press("Enter");
