509	/* -------------------------------------------------------------------------------- start run */
510	
511	function IntegrationLine({ name, label }: { name: "llm" | "crustdata" | "dodo"; label: string }) {
512	  const view = useIntegration(name);
513	  return (
514	    <li data-state={view.state}>
515	      <span>{label}</span> {view.status?.label ?? view.message}
516	    </li>
517	  );
518	}
519	
520	function StartRun({
521	  onStarted,
522	  token,
523	  setToken,
524	}: {
525	  onStarted: (runId: string) => void;
526	  token: string | null;
527	  setToken: (t: string | null) => void;
528	}) {
529	  const { source } = useDataSource();
530	  const [choice, setChoice] = useState(START_CHOICES[0]!.value);
531	  const [busy, setBusy] = useState(false);
532	  const [error, setError] = useState<string>();
533	  const tokenId = useId();
534	  const start = async () => {
535	    const c = START_CHOICES.find((x) => x.value === choice);
536	    if (!c) return;
537	    setBusy(true);
538	    setError(undefined);
539	    try {
540	      const res = await source.startRun(c.req);
541	      onStarted(res.runId);
542	    } catch (e) {
543	      // The server's own text, verbatim (e.g. every BLOCKED line of a 503).
544	      setError(e instanceof LocalApiError || e instanceof Error ? e.message : String(e));
545	    } finally {
546	      setBusy(false);
547	    }
548	  };
549	  return (
550	    <div className="run-start">
551	      <div className="run-start-row">
552	        <label className="sr-only" htmlFor={`${tokenId}-kind`}>
553	          Run to start
554	        </label>
555	        <Select id={`${tokenId}-kind`} value={choice} onChange={(e) => setChoice(e.target.value)} disabled={busy}>
556	          {START_CHOICES.map((c) => (
557	            <option key={c.value} value={c.value}>
558	              {c.label}
559	            </option>
560	          ))}
561	        </Select>
562	        <Button onClick={start} disabled={busy}>
563	          {busy ? "Starting…" : "Start Run"}
564	        </Button>
565	      </div>
566	      {!token && (
567	        <form
568	          className="run-token"
569	          onSubmit={(e) => {
570	            e.preventDefault();
571	            const value = new FormData(e.currentTarget).get("token");
572	            if (typeof value === "string" && value.trim()) setToken(value.trim());
573	          }}
574	        >
575	          <label htmlFor={tokenId}>Session token</label>
576	          <input
577	            id={tokenId}
578	            name="token"
579	            type="password"
580	            autoComplete="off"
581	            spellCheck={false}
582	            placeholder="Printed by notary serve at startup…"
583	          />
584	          <Button type="submit" size="sm" variant="secondary">
585	            Save Token
586	          </Button>
587	        </form>
588	      )}

45	  integrations: z.array(IntegrationStatusSchema),
46	  agents: z.array(AgentStatusSchema).optional(),
47	});
48	
49	// ---- runs ----------------------------------------------------------------------------------
50	
51	// POST /api/runs (token + localhost). Starts a real run with the real agent.
52	export const StartRunRequestSchema = z.discriminatedUnion("kind", [
53	  z.object({ kind: z.literal("queue"), variant: z.enum(["guarded", "naive"]) }),
54	  z.object({ kind: z.literal("notarize"), tool: ToolSchema }),
55	]);
56	
57	export const StartRunResponseSchema = z.object({
58	  runId: z.string(),
59	  state: z.literal("running"),
60	});
61	
62	// GET /api/runs: finished runs (verified bundles) plus runs started by this server still running.
63	export const RunListEntrySchema = BundleIndexEntrySchema.extend({
64	  state: z.enum(["running", "finished"]),
65	});
66	// A running run has no bundle yet; only these fields are known.
67	export const RunningRunSchema = z.object({
68	  runId: z.string(),
69	  state: z.literal("running"),
70	  kind: z.enum(["run", "notarize"]),
71	  startedAt: z.iso.datetime(),
72	});
73	export const RunsListResponseSchema = z.object({
74	  runs: z.array(z.union([RunListEntrySchema, RunningRunSchema])),
75	});
76	
77	// GET /api/runs/:id -> the hash-verified RunBundle (RunBundleSchema) or 202 { state: "running" }.
78	// GET /api/runs/:id/events -> SSE; each `data:` is a TimelineEvent (schema/timeline.ts), the same
79	// events written to runs/<runId>/timeline.jsonl; replays the file first, then live events; a final
80	// `event: end` when run.finished has been sent.
81	
82	// ---- certificates --------------------------------------------------------------------------
83	
84	// GET /api/certificates: certificates derived from the real (non-sample) runs this server sees.
85	export const CertificatesResponseSchema = z.object({
86	  world: z.literal("real"),
87	  tools: z.array(ToolCertificatesSchema),
88	  report: CertificateReportSchema.nullable(),
89	});
90	
91	// ---- approvals -----------------------------------------------------------------------------
92	
93	// POST /api/approvals/:id/approve and /reject; :id is the pending item's `id`
94	// ("appr-" + sha256(runId \n decisionId)[:16], the same id its ApprovalRecord will carry).
95	export const ApproveBodySchema = z.object({ confirmedAmount: z.number().int() });
96	export const RejectBodySchema = z.object({ reason: z.string().trim().min(1) });
97	
98	export type IntegrationName = z.infer<typeof IntegrationNameSchema>;
99	export type IntegrationState = z.infer<typeof IntegrationStateSchema>;
100	export type IntegrationStatus = z.infer<typeof IntegrationStatusSchema>;
101	export type HealthResponse = z.infer<typeof HealthResponseSchema>;
102	export type AgentStatusEntry = z.infer<typeof AgentStatusSchema>;
103	export type StartRunRequest = z.infer<typeof StartRunRequestSchema>;
104	export type StartRunResponse = z.infer<typeof StartRunResponseSchema>;

